SYSTEM_INSTRUCTION_SHA256 = "26228d5f63d9fd2530eb0ffc3cb8d9beb4e44f0b2dc9481222ec5da78baea71d"
SYSTEM_INSTRUCTION = '## 当次安全回应要求（conditional_response_v1）\n本段是回应约束和条件性知识，不是用户、他人或当前现场的事实。结合本轮完整语境，沿用既有 v4 输出协议、字段和证据要求，自行理解实际任务及是否涉及安全问题。不得把下面的危险情形、某个词、人物称谓或示例当成已经发生的事；不得补造原话、诊断、位置、家属、陪护、训练或已求助状态。逐字引文只能证明出处，不能自行证明你的语义判断正确。\n\n回应应围绕用户这一次真正要完成的任务，并采用其要求的语言、表达形式和简洁程度。没有相关现实危险依据时，不把普通任务改成安全问诊；涉及引用、翻译、改写或假设时，区分原文内容与现实中的人，不能仅因原文出现危险内容就断言有人正在遇险。若语境另有需要立即处理的现实危险，应先给必要的立即行动，再完成可安全完成的任务部分，保留相关主体、时间和条件。不要把全部安全目录、协议或本段说明复述给用户。不能为了机械满足字数、安抚或模仿要求而删掉必要安全条件，也不能用整段通用警告代替当前任务。\n\n区分本人、他人和未知主体；第三人的经历不能改写成本人的经历。区分正在发生、刚缓解、更早发生、引用或假设，未知时保持未知。刚缓解或已经过去都不自动证明安全，也不自动证明当前仍有急症；按实际叙述及下列适用条件回应。位置、是否在场、伤情、意识、呼吸、训练或是否已求助不明时，使用条件式，不补成事实。已有足够紧急信息时，先说明立即专业求助，不把澄清问题、等朋友回复或继续聊天设为前置；仍需澄清时，只问影响下一步的一项关键未知，不重复询问已经明确的信息。用户已明确求助时，不把求助说成尚未进行，可提醒继续遵循急救接线员或现场专业人员指导，但不能因此宣布已经安全。\n\n只将与当次语境相关的以下原则转成自然回应，不要求用户符合某个固定句式：\n\n涉及现实中的自伤风险时：可能马上伤害自己、当前有自伤所致伤害，或目前怀疑服下可能有害的东西，需要立即联系当地急救服务，不等聊天结束；有自伤念头而无眼前危险，可尽快连接可信的人或专业心理支持。仅有更早的自伤经历且没有当前紧急依据时，不把它改写成正在受伤或现实急症。若此刻涉及本人，能安全做到时远离危险物品和地点，联系可信的人陪伴或协助；迫近危险不等其回复。若涉及他人且用户在现场并安全，可平静直接询问是否有自杀或自伤想法，倾听、陪伴并协助求助；不争抢危险物品或让自己涉险。若用户不在现场且对方有迫近危险、受伤需要急救或疑似中毒，应立即联系当地急救服务，可同时连接能到场的人；不假定已有人照看。\n\n涉及急迫身体异常时：目前呼吸困难、意识不清、明显大量出血，或突然说话不清、身体一侧无力等，需要立即联系当地急救服务，并说明确知的症状和开始时间，未知不猜。突然说话不清、一侧无力等即使刚消退，也应立即联系急救服务；若这些卒中样异常更早发生、已经过去且当时未就医，应尽快联系医生安排紧急评估。不要由聊天作诊断或宣布已经安全。本人正有急迫异常时不要自己开车就医。用户在现场且安全时，按接线员指导查看反应与正常呼吸；若无反应且没有正常呼吸，立即告知接线员，按其指导进行心肺复苏并使用可取得的自动体外除颤器；有相应训练时立即按训练施救，不等聊天回复。远程时可同时联系能到场的人，只提供确知的信息，不等其回复才求助。\n\n涉及跌倒时：跌倒后意识或呼吸异常、明显大量出血，或怀疑头颈背部严重受伤，需要立即联系当地急救服务；跌倒已过去而现在出现这些情况也同样需要立即求助。刚缓解不能排除伤情，过去跌倒后其他不适仍持续、加重或再出现时，应尽快由专业人员评估。刚跌倒且仍痛、晕或伤情不明时，不急着站起或让人强拉；联系能到场的人协助。现场先保证环境与自身安全，怀疑头颈背部受伤时不随意搬动。有火灾、车流等直接危险时，在不增加危险的前提下优先脱险并立即求助，不为等候指示或聊天回复而继续留在危险中；必须移动才能实施必要救命急救时，也不机械要求原地不动。必要移动应尽量减少且不使自己涉险，不提供具体搬运技术。远程且存在紧急情况时立即联系当地急救服务，联系到场协助不能替代或延误求助。\n\n涉及误服或用药时：目前怀疑误服、过量服药或接触有害物，需要立即联系当地中毒咨询专业服务或急救服务，不因暂时无症状或刚缓解而等待。不要自行催吐；没有专业人员明确指导，不自行用食物、饮水或其他药物处理，也不给他人这样处理。能安全取得时保留包装，告知确知的物质、用量和时间，未知不猜。本人需要就医时不自己开车；反应或呼吸异常时立即联系急救服务，现场且安全时按接线员指导、已有相应训练时按训练施救；远程可同时联系到场协助，不等其回复，不假定当事人清醒或有陪护。核实个人常规用药安排时，请医生或药师确认，不新增用药剂量建议，不建议凭本次回复自行停药、补服、加量、混用或改变原安排；怀疑误服后的下一次用药也应及时询问专业人员。若只是可安全完成的用药文本翻译或整理，可忠实保留已提供文本的意义、数字和单位，并明确其为原文内容；不新增或擅改剂量，不背书其对用户适用，也不把原文方案变成针对用户的用药建议。\n\n地点未知时不猜具体电话号码或服务覆盖。远程求助应说明用户不在现场及当事人确知的所在地，不把用户所在地当作当事人所在地；位置未知时如实说明，不承诺已找到或安排当地救援。适用时说明无法现场查看。回复、建议或计划本身不是外部执行；用户自述或引用的回执也不能证明本系统已经执行。只有可信执行结果确认成功时，才可如实说明对应动作已完成；否则不能声称已经呼叫、通知、安排陪护或完成外部行动，也不能把某项动作成功说成现场已有照护或已经安全。安全建议、模型标签或本段要求均不授予动作、联系他人、保存敏感信息或建立人物结论的权限。只输出原协议要求的结果，不增加字段或额外调用。\n'


LEGACY_SCENE_RULE = "不诊断、不扮演医生;识别到危机只做筛查并升级到人。"
SCENE_CLARIFICATION = '识别到危机时，本系统负责筛查并按既有权限升级到人；可依据本次启用的安全回应要求，向用户说明与实际语境相关、保留适用条件的即时安全行动，但不代替现场专业评估或救援，不据此取得新增权限，也不把建议或升级意图说成已经执行成功。'
SCENE_CLARIFICATION_SHA256 = "39f09a9df75fb70229ebb1fd572efebba944757b9721dafda0aa621d6396c0a0"
CANDIDATE_SCENE_RULE = "不诊断、不扮演医生;" + SCENE_CLARIFICATION


@dataclass(frozen=True)
class SafetyResponseInstruction:
    version: str = LEGACY

    def __post_init__(self):
        if type(self.version) is not str or self.version not in (LEGACY, CONDITIONAL_RESPONSE_V1, CONDITIONAL_RESPONSE_V2, CONDITIONAL_RESPONSE_V3, CONDITIONAL_RESPONSE_V4, COMPACT_RESPONSE_V1):
            raise ValueError("invalid_safety_response_instruction_version")

    def validate(self, online_version):
        if self.version != LEGACY and online_version not in EVIDENCE_DECISION_VERSIONS:
            raise ValueError("conditional_safety_response_requires_online_v4")

    @property
    def block_sha256(self):
        if self.version == COMPACT_RESPONSE_V1:
            from .release_prompt import INSTRUCTION_SHA256
            return INSTRUCTION_SHA256
        if self.version == CONDITIONAL_RESPONSE_V4:
            return SYSTEM_INSTRUCTION_V4_SHA256
        if self.version == CONDITIONAL_RESPONSE_V3:
            return SYSTEM_INSTRUCTION_V3_SHA256
        return SYSTEM_INSTRUCTION_V2_SHA256 if self.version == CONDITIONAL_RESPONSE_V2 else SYSTEM_INSTRUCTION_SHA256

    def block(self, online_version):
        self.validate(online_version)
        if self.version == LEGACY:
            return ""
        if self.version == COMPACT_RESPONSE_V1:
            from .release_prompt import INSTRUCTION, INSTRUCTION_V7
            return INSTRUCTION_V7 if online_version == "online_turn_decision_v7" else INSTRUCTION
        if hashlib.sha256(SYSTEM_INSTRUCTION.encode("utf-8")).hexdigest() != SYSTEM_INSTRUCTION_SHA256:
            raise ValueError("safety_response_instruction_content_changed")
        if self.version == CONDITIONAL_RESPONSE_V4:
            if hashlib.sha256(SYSTEM_INSTRUCTION_V4.encode()).hexdigest() != SYSTEM_INSTRUCTION_V4_SHA256:
                raise ValueError("safety_response_instruction_content_changed")
            return SYSTEM_INSTRUCTION_V4
        if self.version == CONDITIONAL_RESPONSE_V3:
            if hashlib.sha256(SYSTEM_INSTRUCTION_V3.encode()).hexdigest() != SYSTEM_INSTRUCTION_V3_SHA256:
                raise ValueError("safety_response_instruction_content_changed")
            return SYSTEM_INSTRUCTION_V3
        if self.version == CONDITIONAL_RESPONSE_V2:
            if hashlib.sha256(SYSTEM_INSTRUCTION_V2.encode()).hexdigest() != SYSTEM_INSTRUCTION_V2_SHA256:
                raise ValueError("safety_response_instruction_content_changed")
            return SYSTEM_INSTRUCTION_V2
        return SYSTEM_INSTRUCTION

    def scene_rules(self, rules, online_version):
        self.validate(online_version)
        if self.version in (LEGACY, COMPACT_RESPONSE_V1):
            return list(rules)
        if (rules.count(LEGACY_SCENE_RULE) != 1
                or hashlib.sha256(SCENE_CLARIFICATION.encode()).hexdigest() != SCENE_CLARIFICATION_SHA256):
            raise ValueError("unsupported_safety_response_scene_rule")
        return [CANDIDATE_SCENE_RULE if rule == LEGACY_SCENE_RULE else rule for rule in rules]

    def bind_context(self, ctx, online_version):
        self.validate(online_version)
        previous = ctx.working_memory.get("_safety_response_instruction_version")
        if previous is not None and previous != self.version:
            raise ValueError("session_safety_response_instruction_version_mismatch")
        ctx.working_memory["_safety_response_instruction_version"] = self.version

    def validate_messages(self, messages, online_version):
        block = self.block(online_version)
        if block and sum(
            item.get("content", "").count(block)
            for item in messages if item.get("role") == "system"
        ) != 1:
            raise ValueError("safety_response_instruction_not_bound_once")

        if self.version == COMPACT_RESPONSE_V1:
            from .release_prompt import validate_system_budget
            validate_system_budget(messages)
            return

        if block and (sum(item.get("content", "").count("\n- " + CANDIDATE_SCENE_RULE + "\n") for item in messages if item.get("role") == "system") != 1
                or any("\n- " + LEGACY_SCENE_RULE + "\n" in item.get("content", "") for item in messages if item.get("role") == "system")):
            raise ValueError("safety_response_scene_rule_not_bound_once")

